SysDataModelXML.SQLUpdateScript:
--LINKJSONDATASUBMIT DECLARE @USER VARCHAR(30) = '#LOGIN_USER#'; DECLARE @CRETIM DATETIME =GETDATE(); DECLARE @DOCNUM VARCHAR(100) =N'#LINKDOCNUM({5},PRA)#';
DECLARE @json NVARCHAR(MAX); SET @json = N'#LINKJSON{$.formData}#'; DECLARE @TABLE_1 NVARCHAR(MAX); SET @TABLE_1 = N'#LINKJSON{$.TABLE_1}#';
MERGE INTO PREQAH D USING ( SELECT TOP 1 @DOCNUM as DOCNUM, DOCGRP,@CRETIM DOCDAT,SITE,FAC,DEPT,GRP,RESNO,PRJNUM FROM OPENJSON(@JSON) WITH ( DOCGRP varchar(30) '$.DOCGRP' --请求类型 ,SITE varchar(30) '$.SITE' --地点 ,FAC varchar(30) '$.FAC' --工厂 ,DEPT varchar(30) '$.DEPT' --申请部门 ,GRP varchar(30) '$.GRP' --申请班组 ,RESNO varchar(30) '$.RESNO' --申请人 ,PRJNUM varchar(30) '$.PRJNUM' --项目编号
) ) S ON D.DOCNUM = S.DOCNUM WHEN MATCHED THEN UPDATE SET UPDUSR = @USER , UPDTIM = GETDATE() WHEN NOT MATCHED THEN INSERT ( DOCNUM ,DOCGRP ,DOCDAT ,DOCSTA ,SITE ,FAC ,DEPT ,GRP ,RESNO ,PRJNUM ,WFLSTA ,CREUSR ,CRETIM ) VALUES ( DOCNUM ,DOCGRP ,DOCDAT ,'1' ,SITE ,FAC ,DEPT ,GRP ,RESNO ,PRJNUM ,'1' ,@USER ,@CRETIM ); MERGE INTO PREQAL D USING ( SELECT @DOCNUM AS DOCNUM, ROW_NUMBER() OVER (ORDER BY (SELECT NULL))*10 AS DOCLIN,A.ITMNO,A.ITMVER ,A.REQDAT,A.UOM,M.PUUCOE UOMCOE,A.QTY,M.PUUCOE*A.QTY QTYSTU,M.STU,A.REMARK,A.DOCSTA,A.CLOREA FROM OPENJSON(@TABLE_1) WITH ( ITMNO varchar(30) '$.ITMNO' --产品编码 ,ITMVER nvarchar(30) '$.ITMVER' --产品版本 ,REQDAT date '$.REQDAT' --要求日期 ,UOM nvarchar(6) '$.UOM' --单据单位 ,QTY decimal(18,6) '$.QTY' --采购单位数量 ,REMARK nvarchar(250) '$.REMARK' --行备注 ,DOCSTA varchar(1) '$.DOCSTA' --单据状态 ,CLOREA nvarchar(60) '$.CLOREA' --关闭原因 ) A LEFT JOIN ITM M ON A.ITMNO =M.ITMNO ) S ON D.DOCNUM = S.DOCNUM AND D.DOCLIN=S.DOCLIN WHEN MATCHED THEN UPDATE SET UPDUSR = @USER , UPDTIM = GETDATE() WHEN NOT MATCHED THEN INSERT ( DOCNUM ,DOCLIN ,ITMNO ,ITMVER ,REQDAT ,UOM ,UOMCOE ,QTY ,STU ,QTYSTU ,REMARK ,DOCSTA ,CLOREA ,CREUSR ,CRETIM ) VALUES ( DOCNUM ,DOCLIN ,ITMNO ,ITMVER ,REQDAT ,UOM ,UOMCOE ,QTY ,STU ,QTYSTU ,REMARK ,'1' ,CLOREA ,@USER ,@CRETIM );

SysDataModelXML.SQLNew:
--LINKADDNEWROWS --LINKJSONDATASUBMIT DECLARE @USER VARCHAR(30) = '#LOGIN_USER#'; DECLARE @CRETIM DATETIME =GETDATE();
DECLARE @json NVARCHAR(MAX); SET @json = N'#LINKJSON{$.formData}#'; DECLARE @TABLE_1 NVARCHAR(100); SET @TABLE_1 = N'#LINKJSON{$.TABLE_1}#';
MERGE INTO PREQAH D USING ( SELECT * FROM OPENJSON(@json) WITH ( DOCNUM varchar(30) '$.DOCNUM' --请求填报单号 ,DOCGRP varchar(30) '$.DOCGRP' --请求类型 ,DOCDAT date '$.DOCDAT' --单据日期 ,DOCSTA varchar(1) '$.DOCSTA' --单据状态 ,SITE varchar(30) '$.SITE' --地点 ,FAC varchar(30) '$.FAC' --工厂 ,DEPT varchar(30) '$.DEPT' --申请部门 ,GRP varchar(30) '$.GRP' --申请班组 ,RESNO varchar(30) '$.RESNO' --申请人 ,PRJNUM varchar(30) '$.PRJNUM' --项目编号 ,WFLSTA varchar(10) '$.WFLSTA' --工作流状态 ,CLOREA nvarchar(60) '$.CLOREA' --关闭原因 ,PRNCNT tinyint '$.PRNCNT' --打印次数 )) S ON D.DOCNUM = S.DOCNUM WHEN MATCHED THEN UPDATE SET UPDUSR = @USER , UPDTIM = GETDATE() WHEN NOT MATCHED THEN INSERT ( DOCNUM ,DOCGRP ,DOCDAT ,DOCSTA ,SITE ,FAC ,DEPT ,GRP ,RESNO ,PRJNUM ,WFLSTA ,CLOREA ,PRNCNT ,CREUSR ,CRETIM ) VALUES ( DOCNUM ,DOCGRP ,DOCDAT ,DOCSTA ,SITE ,FAC ,DEPT ,GRP ,RESNO ,PRJNUM ,WFLSTA ,CLOREA ,PRNCNT ,@USER ,@CRETIM ); MERGE INTO PREQAL D USING ( SELECT * FROM OPENJSON(@TABLE_1) WITH ( ,DOCNUM varchar(30) '$.DOCNUM' --请求填报单号 ,DOCLIN int '$.DOCLIN' --行号 ,ITMNO varchar(30) '$.ITMNO' --产品编码 ,ITMVER nvarchar(30) '$.ITMVER' --产品版本 ,REQDAT date '$.REQDAT' --要求日期 ,UOM nvarchar(6) '$.UOM' --单据单位 ,UOMCOE decimal(18,6) '$.UOMCOE' --换算系数 ,QTY decimal(18,6) '$.QTY' --采购单位数量 ,STU nvarchar(6) '$.STU' --库存单位 ,QTYSTU decimal(18,6) '$.QTYSTU' --库存单位数量 ,REMARK nvarchar(250) '$.REMARK' --行备注 ,DOCSTA varchar(1) '$.DOCSTA' --单据状态 ,CLOREA nvarchar(60) '$.CLOREA' --关闭原因 )) S ON D.DOCNUM = S.DOCNUM WHEN MATCHED THEN UPDATE SET UPDUSR = @USER , UPDTIM = GETDATE() WHEN NOT MATCHED THEN INSERT ( DOCNUM ,DOCLIN ,ITMNO ,ITMVER ,REQDAT ,UOM ,UOMCOE ,QTY ,STU ,QTYSTU ,REMARK ,DOCSTA ,CLOREA ,CREUSR ,CRETIM ) VALUES ( DOCNUM ,DOCLIN ,ITMNO ,ITMVER ,REQDAT ,UOM ,UOMCOE ,QTY ,STU ,QTYSTU ,REMARK ,DOCSTA ,CLOREA ,@USER ,@CRETIM );
